# Terraform Module: S3 + RDS + IAM

I'll provide a production-ready Terraform module structure supporting dev/prod environments via `.tfvars` files (workspaces are optional but not needed here).

## Directory Structure

```
terraform/
├── modules/
│   ├── s3/
│   │   ├── main.tf
│   │   ├── variables.tf
│   │   └── outputs.tf
│   ├── rds/
│   │   ├── main.tf
│   │   ├── variables.tf
│   │   └── outputs.tf
│   └── iam/
│       ├── main.tf
│       ├── variables.tf
│       └── outputs.tf
├── main.tf
├── variables.tf
├── outputs.tf
├── dev.tfvars
├── prod.tfvars
└── terraform.tfvars.example
```

---

## `modules/s3/main.tf`

```hcl
resource "aws_s3_bucket" "app_bucket" {
  bucket = var.bucket_name

  tags = merge(
    var.common_tags,
    {
      Name = var.bucket_name
    }
  )
}

resource "aws_s3_bucket_versioning" "app_bucket" {
  bucket = aws_s3_bucket.app_bucket.id

  versioning_configuration {
    status = "Enabled"
  }
}

resource "aws_s3_bucket_server_side_encryption_configuration" "app_bucket" {
  bucket = aws_s3_bucket.app_bucket.id

  rule {
    apply_server_side_encryption_by_default {
      sse_algorithm      = var.enable_kms ? "aws:kms" : "AES256"
      kms_master_key_id  = var.enable_kms ? aws_kms_key.s3_key[0].arn : null
    }
  }
}

resource "aws_s3_bucket_public_access_block" "app_bucket" {
  bucket = aws_s3_bucket.app_bucket.id

  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_kms_key" "s3_key" {
  count = var.enable_kms ? 1 : 0

  description             = "KMS key for S3 bucket ${var.bucket_name}"
  deletion_window_in_days = 10
  enable_key_rotation     = true

  tags = var.common_tags
}

resource "aws_kms_alias" "s3_key_alias" {
  count = var.enable_kms ? 1 : 0

  name          = "alias/${var.bucket_name}-key"
  target_key_id = aws_kms_key.s3_key[0].key_id
}

# Cross-region replication for prod (optional)
resource "aws_s3_bucket_replication_configuration" "app_bucket" {
  count = var.enable_replication ? 1 : 0

  depends_on = [aws_s3_bucket_versioning.app_bucket]

  bucket = aws_s3_bucket.app_bucket.id
  role   = var.replication_role_arn

  rule {
    id     = "ReplicateAll"
    status = "Enabled"

    destination {
      bucket       = var.replica_bucket_arn
      storage_class = "STANDARD_IA"

      encryption_configuration {
        replica_kms_key_id = var.replica_kms_key_id
      }
    }
  }
}
```

## `modules/s3/variables.tf`

```hcl
variable "bucket_name" {
  description = "Name of the S3 bucket"
  type        = string

  validation {
    condition     = can(regex("^[a-z0-9][a-z0-9.-]*[a-z0-9]$", var.bucket_name))
    error_message = "Bucket name must follow AWS S3 naming rules."
  }
}

variable "common_tags" {
  description = "Common tags for all resources"
  type        = map(string)
  default     = {}
}

variable "enable_kms" {
  description = "Enable KMS encryption (true for prod, false for dev)"
  type        = bool
  default     = false
}

variable "enable_replication" {
  description = "Enable cross-region replication"
  type        = bool
  default     = false
}

variable "replica_bucket_arn" {
  description = "ARN of the replica bucket"
  type        = string
  default     = ""
}

variable "replication_role_arn" {
  description = "ARN of IAM role for replication"
  type        = string
  default     = ""
}

variable "replica_kms_key_id" {
  description = "KMS key ID for replica bucket encryption"
  type        = string
  default     = ""
}
```

## `modules/s3/outputs.tf`

```hcl
output "bucket_id" {
  description = "S3 bucket ID"
  value       = aws_s3_bucket.app_bucket.id
}

output "bucket_arn" {
  description = "S3 bucket ARN"
  value       = aws_s3_bucket.app_bucket.arn
}

output "bucket_region" {
  description = "S3 bucket region"
  value       = aws_s3_bucket.app_bucket.region
}

output "kms_key_id" {
  description = "KMS key ID for S3 encryption"
  value       = var.enable_kms ? aws_kms_key.s3_key[0].id : null
}
```

