## `modules/rds/main.tf`

```hcl
resource "aws_db_subnet_group" "rds_subnet_group" {
  name       = "${var.instance_name}-subnet-group"
  subnet_ids = var.subnet_ids

  tags = merge(
    var.common_tags,
    {
      Name = "${var.instance_name}-subnet-group"
    }
  )
}

resource "aws_rds_cluster_parameter_group" "postgres" {
  name        = "${var.instance_name}-cluster-pg"
  family      = var.parameter_group_family
  description = "Cluster parameter group for ${var.instance_name}"

  parameter {
    name  = "log_statement"
    value = "all"
  }

  tags = var.common_tags
}

resource "aws_db_instance" "postgres" {
  identifier            = var.instance_name
  engine                = "postgres"
  engine_version        = var.postgres_version
  instance_class        = var.instance_class
  allocated_storage     = var.allocated_storage
  storage_type          = "gp3"
  storage_encrypted     = true
  kms_key_id            = var.kms_key_id

  db_name  = var.db_name
  username = var.master_username
  password = var.master_password  # Use random password + Secrets Manager in production

  multi_az               = var.multi_az
  publicly_accessible    = false
  db_subnet_group_name   = aws_db_subnet_group.rds_subnet_group.name
  parameter_group_name   = aws_db_parameter_group.postgres.name
  vpc_security_group_ids = var.security_group_ids

  deletion_protection       = var.deletion_protection
  backup_retention_period   = var.backup_retention_days
  preferred_backup_window   = "03:00-04:00"
  preferred_maintenance_window = "mon:04:00-mon:05:00"

  skip_final_snapshot       = false
  final_snapshot_identifier = "${var.instance_name}-final-snapshot-${formatdate("YYYY-MM-DD-hhmm", timestamp())}"

  enable_cloudwatch_logs_exports = ["postgresql"]
  copy_tags_to_snapshot          = true

  tags = merge(
    var.common_tags,
    {
      Name = var.instance_name
    }
  )

  depends_on = [aws_db_subnet_group.rds_subnet_group]
}

resource "aws_db_parameter_group" "postgres" {
  name   = "${var.instance_name}-pg"
  family = var.parameter_group_family

  parameter {
    name  = "log_statement"
    value = "all"
  }

  tags = var.common_tags
}
```

## `modules/rds/variables.tf`

```hcl
variable "instance_name" {
  description = "RDS instance identifier"
  type        = string

  validation {
    condition     = can(regex("^[a-z0-9][a-z0-9-]*[a-z0-9]$", var.instance_name))
    error_message = "Instance name must start/end with alphanumeric and contain only alphanumeric and hyphens."
  }
}

variable "instance_class" {
  description = "RDS instance class (e.g., db.t3.micro, db.t3.medium)"
  type        = string
}

variable "postgres_version" {
  description = "PostgreSQL engine version"
  type        = string
  default     = "15.3"
}

variable "parameter_group_family" {
  description = "DB parameter group family"
  type        = string
  default     = "postgres15"
}

variable "allocated_storage" {
  description = "Allocated storage in GB"
  type        = number
  default     = 20
}

variable "db_name" {
  description = "Initial database name"
  type        = string
  default     = "appdb"
}

variable "master_username" {
  description = "Master database username"
  type        = string
  sensitive   = true
}

variable "master_password" {
  description = "Master database password (use AWS Secrets Manager in production)"
  type        = string
  sensitive   = true

  validation {
    condition     = length(var.master_password) >= 8
    error_message = "Password must be at least 8 characters."
  }
}

variable "multi_az" {
  description = "Enable Multi-AZ deployment"
  type        = bool
  default     = false
}

variable "deletion_protection" {
  description = "Enable deletion protection"
  type        = bool
  default     = true
}

variable "backup_retention_days" {
  description = "Backup retention period (days)"
  type        = number
  default     = 7

  validation {
    condition     = var.backup_retention_days >= 7
    error_message = "Backup retention must be at least 7 days."
  }
}

variable "kms_key_id" {
  description = "KMS key ID for RDS encryption"
  type        = string
}

variable "subnet_ids" {
  description = "List of subnet IDs for DB subnet group"
  type        = list(string)
}

variable "security_group_ids" {
  description = "List of VPC security group IDs"
  type        = list(string)
}

variable "common_tags" {
  description = "Common tags for all resources"
  type        = map(string)
  default     = {}
}
```

