## `modules/iam/main.tf`

```hcl
resource "aws_iam_role" "service_account" {
  name               = "${var.role_name}-role"
  assume_role_policy = var.trust_policy

  tags = var.common_tags
}

resource "aws_iam_role_policy" "s3_access" {
  count = var.enable_s3_policy ? 1 : 0

  name   = "${var.role_name}-s3-policy"
  role   = aws_iam_role.service_account.id
  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "S3BucketAccess"
        Effect = "Allow"
        Action = [
          "s3:GetObject",
          "s3:PutObject",
          "s3:DeleteObject",
          "s3:ListBucket",
        ]
        Resource = [
          "${var.s3_bucket_arn}",
          "${var.s3_bucket_arn}/*",
        ]
      },
      {
        Sid    = "S3VersioningAccess"
        Effect = "Allow"
        Action = [
          "s3:GetObjectVersion",
          "s3:ListBucketVersions",
        ]
        Resource = [
          "${var.s3_bucket_arn}",
          "${var.s3_bucket_arn}/*",
        ]
      }
    ]
  })
}

resource "aws_iam_role_policy" "rds_access" {
  count = var.enable_rds_policy ? 1 : 0

  name   = "${var.role_name}-rds-policy"
  role   = aws_iam_role.service_account.id
  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "RDSConnect"
        Effect = "Allow"
        Action = [
          "rds:DescribeDBInstances",
          "rds:DescribeDBClusters",
        ]
        Resource = [
          var.rds_resource_arn,
        ]
      }
    ]
  })
}

resource "aws_iam_role_policy" "kms_access" {
  count = var.enable_kms_policy ? 1 : 0

  name   = "${var.role_name}-kms-policy"
  role   = aws_iam_role.service_account.id
  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "KMSDecrypt"
        Effect = "Allow"
        Action = [
          "kms:Decrypt",
          "kms:GenerateDataKey",
          "kms:DescribeKey",
        ]
        Resource = var.kms_key_arns
      }
    ]
  })
}

resource "aws_iam_access_key" "service_account" {
  count = var.create_access_key ? 1 : 0

  user = aws_iam_user.service_account[0].name

  lifecycle {
    create_before_destroy = true
  }
}

resource "aws_iam_user" "service_account" {
  count = var.create_access_key ? 1 : 0

  name = "${var.role_name}-user"

  tags = var.common_tags
}

resource "aws_iam_user_policy_attachment" "service_account" {
  count = var.create_access_key ? 1 : 0

  user       = aws_iam_user.service_account[0].name
  policy_arn = aws_iam_policy.service_account_inline[0].arn
}

resource "aws_iam_policy" "service_account_inline" {
  count = var.create_access_key ? 1 : 0

  name   = "${var.role_name}-inline-policy"
  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "AllowS3"
        Effect = "Allow"
        Action = [
          "s3:GetObject",
          "s3:ListBucket",
        ]
        Resource = [
          "${var.s3_bucket_arn}",
          "${var.s3_bucket_arn}/*",
        ]
      },
    ]
  })
}
```

