## Root: `main.tf`

```hcl
terraform {
  required_version = ">= 1.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
  # Uncomment to store state remotely
  # backend "s3" {
  #   bucket         = "my-terraform-state"
  #   key            = "app-infrastructure/terraform.tfstate"
  #   region         = "us-east-1"
  #   encrypt        = true
  #   dynamodb_table = "terraform-locks"
  # }
}

provider "aws" {
  region = var.aws_region

  default_tags {
    tags = local.common_tags
  }
}

locals {
  common_tags = merge(
    var.common_tags,
    {
      Environment = var.environment
      ManagedBy   = "Terraform"
      CreatedBy   = var.created_by
    }
  )
}

# Security Group for RDS
resource "aws_security_group" "rds" {
  name_prefix = "${var.environment}-rds-"
  description = "Security group for RDS PostgreSQL"
  vpc_id      = var.vpc_id

  ingress {
    from_port       = 5432
    to_port         = 5432
    protocol        = "tcp"
    security_groups = var.app_security_group_ids
  }

  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }

  tags = local.common_tags
}

# KMS Key for encryption
resource "aws_kms_key" "rds" {
  description             = "KMS key for RDS encryption in ${var.environment}"
  deletion_window_in_days = 10
  enable_key_rotation     = true

  tags = local.common_tags
}

resource "aws_kms_alias" "rds" {
  name          = "alias/${var.environment}-rds-key"
  target_key_id = aws_kms_key.rds.key_id
}

# S3 Module
module "s3" {
  source = "./modules/s3"

  bucket_name    = var.s3_bucket_name
  enable_kms     = var.environment == "prod"
  enable_replication = var.environment == "prod" && var.enable_s3_replication

  replica_bucket_arn = var.environment == "prod" ? aws_s3_bucket.replica[0].arn : ""
  replication_role_arn = var.environment == "prod" ? aws_iam_role.s3_replication[0].arn : ""
  replica_kms_key_id = var.environment == "prod" ? aws_kms_key.s3_replica[0].id : ""

  common_tags = local.common_tags
}

# Replica bucket for prod
resource "aws_s3_bucket" "replica" {
  count  = var.environment == "prod" && var.enable_s3_replication ? 1 : 0
  bucket = "${var.s3_bucket_name}-replica-us-west-2"
  region = "us-west-2"

  tags = local.common_tags
}

resource "aws_kms_key" "s3_replica" {
  count = var.environment == "prod" && var.enable_s3_replication ? 1 : 0

  provider                = aws.us_west_2
  description             = "KMS key for S3 replica bucket"
  deletion_window_in_days = 10
  enable_key_rotation     = true

  tags = local.common_tags
}

resource "aws_iam_role" "s3_replication" {
  count = var.environment == "prod" && var.enable_s3_replication ? 1 : 0

  name = "${var.environment}-s3-replication-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Principal = {
          Service = "s3.amazonaws.com"
        }
        Action = "sts:AssumeRole"
      }
    ]
  })

  tags = local.common_tags
}

# RDS Module
module "rds" {
  source = "./modules/rds"

  instance_name        = var.rds_instance_name
  instance_class       = var.rds_instance_class
  postgres_version     = var.postgres_version
  allocated_storage    = var.rds_allocated_storage
  multi_az             = var.environment == "prod"
  deletion_protection  = true
  backup_retention_days = var.backup_retention_days

  master_username = var.rds_master_username
  master_password = var.rds_master_password

  kms_key_id         = aws_kms_key.rds.id
  subnet_ids         = var.private_subnet_ids
  security_group_ids = [aws_security_group.rds.id]

  common_tags = local.common_tags
}

# IAM Module for service account
module "iam_service_account" {
  source = "./modules/iam"

  role_name = "${var.environment}-app-service-account"

  trust_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Principal = {
          AWS = "arn:aws:iam::${data.aws_caller_identity.current.account_id}:role/eks-pod-execution-role"
        }
        Action = "sts:AssumeRole"
      }
    ]
  })

  enable_s3_policy  = true
  enable_rds_policy = true
  enable_kms_policy = true
  create_access_key = var.environment == "dev"

  s3_bucket_arn      = module.s3.bucket_arn
  rds_resource_arn   = module.rds.arn
  kms_key_arns       = [aws_kms_key.rds.arn, var.environment == "prod" ? aws_kms_key.s3_replica[0].arn : aws_kms_key.rds.arn]

  common_tags = local.common_tags
}

data "aws_caller_identity" "current" {}
```

